package com.yeyamo_mobile.api.recommendation_service.infrastructure.outbox;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.Map;import org.junit.jupiter.api.Test;import org.mockito.ArgumentCaptor;import com.fasterxml.jackson.databind.ObjectMapper;
class JpaRecommendationOutboxAdapterTest{@Test void persistsVersionedRecommendationEnvelope()throws Exception{var repo=mock(RecommendationOutboxRepository.class);var mapper=new ObjectMapper().findAndRegisterModules();new JpaRecommendationOutboxAdapter(repo,mapper).append("recommendation.generated","u1","corr-1",Map.of("count",3));var captor=ArgumentCaptor.forClass(RecommendationOutboxEvent.class);verify(repo).save(captor.capture());var event=mapper.readTree(captor.getValue().payload);assertEquals("recommendation.generated",event.path("eventType").asText());assertEquals(1,event.path("eventVersion").asInt());assertEquals("u1",event.path("aggregateId").asText());assertEquals(3,event.path("payload").path("count").asInt());}}
